sys_security_acl.script:
// ACL Script for x_kp101_kpmg_res_0_industry_experience
// Purpose: Allow write if the current user matches the resource name; otherwise, deny

(function() {
	// Server-side ACL script

	// Explicit error handling for missing record or field
	if (!current || !current.isValidRecord()) {
		gs.info('ACL: Invalid or missing current record for industry experience', 'x_kp101_kpmg_res_0_industry_experience');
		return false;
	}

	// Get the resource name from the record
	var resource = current.resource.resource_name.sys_id;
	if (!resource) {
		gs.info('ACL: user field is empty on industry experience ' + current.getUniqueValue(), 'x_kp101_kpmg_res_0_industry_experience');
		return false;
	}

	var loggedUserID = gs.getUserID();
	if (!loggedUserID) {
		gs.info('ACL: Unable to retrieve current user ID', 'x_kp101_kpmg_res_0_industry_experience');
		return false;
	}

	// Validate user membership
	if(gs.getUser().isMemberOf('Resource Hub Managers') ||gs.getUser().isMemberOf('Resource Hub Admins')){
		// Allow write
		return true;
	}

	// Trim and compare names for robustness
	if (resource == loggedUserID) {
		// Allow write
		return true;
	}
	// Deny if not matching
	return false;
})();
